package com.cryptox.service; import com.cryptox.dto.*; import org.springframework.beans.factory.annotation.*; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import java.math.*; import java.util.*;
@Service public class TradeOrchestrator{final RestClient client; @Value("${services.market.url}") String market; @Value("${services.wallet.url}") String wallet; @Value("${app.internal-key}") String key; final Map<String,String> ids=Map.of("BTC","bitcoin","ETH","ethereum","USDT","tether","BNB","binancecoin","SOL","solana","XRP","ripple","DOGE","dogecoin","ADA","cardano"); TradeOrchestrator(RestClient.Builder b){client=b.build();}
public Set<String> supported(){return ids.keySet();} public BigDecimal price(String s){String id=ids.get(s.toUpperCase());if(id==null)throw new IllegalArgumentException("Unsupported coin: "+s); Map m=client.get().uri(market+"/api/market/prices?coins="+id+"&vsCurrencies=usd").retrieve().body(Map.class); return new BigDecimal(((Map)m.get(id)).get("usd").toString());}
InternalTradeResponse exec(String u,String type,String f,BigDecimal fa,String t,BigDecimal ta,BigDecimal p){return client.post().uri(wallet+"/internal/trades").header("X-Internal-Key",key).body(new InternalTradeRequest(u,type,f,fa,t,ta,p)).retrieve().body(InternalTradeResponse.class);}
public TradeResponse buy(String u,BuyRequest r){String c=r.getCoinSymbol().toUpperCase();if(c.equals("USDT"))throw new IllegalArgumentException("Cannot buy USDT with USDT");BigDecimal p=price(c), amt=r.getUsdtAmount().divide(p,10,RoundingMode.DOWN);var x=exec(u,"BUY","USDT",r.getUsdtAmount(),c,amt,p);return response(x,"Just bought "+amt.stripTrailingZeros().toPlainString()+" "+c+" for "+r.getUsdtAmount()+" USDT on CryptoX 🚀");}
public TradeResponse sell(String u,SellRequest r){String c=r.getCoinSymbol().toUpperCase();if(c.equals("USDT"))throw new IllegalArgumentException("Cannot sell USDT for USDT");BigDecimal p=price(c),amt=r.getCoinAmount().multiply(p).setScale(10,RoundingMode.DOWN);var x=exec(u,"SELL",c,r.getCoinAmount(),"USDT",amt,p);return response(x,"Just sold "+r.getCoinAmount()+" "+c+" for "+amt+" USDT on CryptoX 💰");}
public TradeResponse swap(String u,SwapRequest r){String f=r.getFromCoinSymbol().toUpperCase(),t=r.getToCoinSymbol().toUpperCase();if(f.equals(t))throw new IllegalArgumentException("Cannot swap a coin into itself");BigDecimal fp=price(f),tp=price(t),to=r.getAmount().multiply(fp).divide(tp,10,RoundingMode.DOWN),rate=fp.divide(tp,10,RoundingMode.DOWN);var x=exec(u,"SWAP",f,r.getAmount(),t,to,rate);return response(x,"Just swapped "+r.getAmount()+" "+f+" → "+to+" "+t+" on CryptoX 🔄");}
TradeResponse response(InternalTradeResponse x,String share){return new TradeResponse(x.transactionId(),x.type(),x.fromCoinSymbol(),x.fromAmount(),x.toCoinSymbol(),x.toAmount(),x.executionPriceUsd(),x.timestamp(),share);}}